"""Four source-specific reviewed scan adapters; never auto-approve OCR."""
import argparse,importlib.util,json,re,hashlib
from pathlib import Path
sp=importlib.util.spec_from_file_location('h',Path(__file__).with_name('reviewed-ocr.py'));h=importlib.util.module_from_spec(sp);sp.loader.exec_module(h)
p=argparse.ArgumentParser();p.add_argument('--cache',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();b=h.DraftBatch(a.cache,a.output)
def source(sid):
 raw=json.load(open(h.ROOT/'import/prepared'/(sid+'.json')));assert raw['sha256']==hashlib.sha256((a.cache/(sid+'.pdf')).read_bytes()).hexdigest();return raw,[p['text'] for p in raw['pages']]
def read(text,starts,fix=()):
 text=h.fixes(text,fix);text=text[text.index(starts[0]):];parts=h.split(text,starts);assert h.m.clean(' '.join(parts))==h.m.clean(text);return parts
def labelled(parts):return [{'label':chr(65+i),'text':t} for i,t in enumerate(parts)]
def bank(texts):return [{'value':chr(65+i),'text':t} for i,t in enumerate(texts)]
def mc(start,prompts,opts,page=3):return {'type':'mc-one','sourcePages':[page],'sourceInstructions':f'Questions {start} – {start+len(prompts)-1} Choose the correct letter, A, B, C or D. Write the correct letter on your answer sheet.','questions':[{'n':start+i,'prompt':p,'options':bank(o)} for i,(p,o) in enumerate(zip(prompts,opts))]}
def yn(start,texts,page=3,part=3,word='claims'):
 g=h.tf(start,texts,page,part);g['type']='ynng';g['sourceInstructions']=f'Questions {start} – {start+len(texts)-1} Do the following statements agree with the {word} of the writer in Reading Passage {part}? In boxes on your answer sheet, write YES if the statement agrees with the {word} of the writer NO if the statement contradicts the {word} of the writer NOT GIVEN if it is impossible to say what the writer thinks about this';return g
def inputg(start,end,text,title=None,limit='ONE WORD ONLY',task='summary',page=4):
 g=h.summary(start,end,title,text,page);g.update(task=task,wordLimit=limit);g['sourceInstructions']=g['sourceInstructions'].replace('ONE WORD ONLY',limit).replace('Complete the summary','Complete the '+task);return g
def drag(start,end,text,options,title=None,page=4):
 g=inputg(start,end,text,title,page=page);g.update(type='summary-drag',bank=bank(options),reuse=False);g.pop('wordLimit');g['sourceInstructions']=f'Questions {start} – {end} Complete the summary using the list of words and phrases, A-{chr(64+len(options))}, below. Write the correct letter on your answer sheet.';return g
def info(start,texts,letters,part,reuse=False,page=3):
 n=len(letters);count={5:'five',7:'seven',8:'eight',9:'nine'}[n];return {'type':'matching-info','sourcePages':[page],'sourceInstructions':f'Questions {start} – {start+len(texts)-1} Reading Passage {part} has {count} paragraphs, A-{letters[-1]}. Which paragraph contains the following information? Write the correct letter on your answer sheet.'+(' NB You may use any letter more than once.' if reuse else ''),'questions':h.qs(start,texts),'letters':list(letters),'paragraphCount':n,'reuse':reuse}
def endings(start,prompts,options,page=4):return {'type':'matching-endings','sourcePages':[page],'sourceInstructions':f'Questions {start} – {start+len(prompts)-1} Complete each sentence with the correct ending, A-{chr(64+len(options))}, below. Write the correct letter on your answer sheet.','questions':h.qs(start,prompts),'bank':bank(options),'reuse':False}
def multi(numbers,prompt,options,page=4):
 return {'type':'mc-two','sourcePages':[page],'sourceInstructions':f'Questions {numbers[0]} – {numbers[-1]} Choose '+('TWO' if len(numbers)==2 else 'THREE')+f' letters, A-{chr(64+len(options))}. Write the correct letters on your answer sheet.','numbers':numbers,'selectionCount':len(numbers),'prompt':prompt,'options':bank(options)}
def save(job,sid,title,part,paras,groups,raw,fix,subtitle=None,footnotes=None):b.save(job,sid,title,part,paras,groups,raw,fix,subtitle,footnotes)

def headings(start,count,texts,page=1):
 roman=['i','ii','iii','iv','v','vi','vii','viii','ix','x'];return {'type':'matching-headings','sourcePages':[page],'sourceInstructions':f'Questions {start} – {start+count-1} Choose the correct heading for each paragraph from the list of headings below. Write the correct number, i-{roman[len(texts)-1]}, on your answer sheet.','questions':[{'n':start+i,'paragraph':i} for i in range(count)],'bank':[{'value':v,'text':t} for v,t in zip(roman,texts)],'reuse':False}

